{
  "findings": [
    {
      "ref": "[D528]",
      "area": "data",
      "claim": "A parent reports that Disney failed to properly label videos as made for kids, leading to collection of children's personal data without parental consent.",
      "stance": "risk",
      "quote": "The primary allegation is that Disney had failed to properly use the \"Made for Kids\" (MFK) designation for hundreds of its YouTube videos. This label is a critical compliance tool that triggers several automated protections, such as disabling personalized ads and preventing data collection."
    },
    {
      "ref": "[D528]",
      "area": "data",
      "claim": "A parent reports that Disney's failure to label videos resulted in YouTube collecting personal information and placing targeted advertisements on child-directed videos on Disney's behalf.",
      "stance": "risk",
      "quote": "Disney’s failure to label the videos correctly “results in YouTube collecting personal information and placing targeted advertisements on child-directed videos on Disney’s behalf,\" according to one [report](https://www.disneyfoodblog.com/2025/12/31/disney-set-to-pay-10-million-over-alleged-childrens-privacy-law-violations/)."
    },
    {
      "ref": "[D527]",
      "area": "age_gating",
      "claim": "A parent reports that Disney must create a program that complies with YouTube's privacy law and requires parental consent before collecting information from children under 13.",
      "stance": "mitigation",
      "quote": "It also requires its websites, apps and other online services aimed at children under 13 to notify parents about the types of personal information collected, as well as gain parental consent before collecting the information."
    },
    {
      "ref": "[D527]",
      "area": "contact",
      "claim": "A parent reports that Disney's YouTube content may allow strangers to message or voice chat with children, but the text does not specify whether this is enabled by default or can be turned off.",
      "stance": "neutral",
      "quote": "The case involves Disney Worldwide Services Inc and Disney Entertainment Operations LLC, and prevents the company from operating on YouTube in ways that violate the Children’s Online Privacy Protection Act (COPPA) and its implementing regulations in connection with Disney's YouTube video content, the Justice Department said last week."
    }
  ]
}
